arguments.query:
CREATE TABLE IF NOT EXISTS todos (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS todo_deps (todo_id TEXT, depends_on TEXT, PRIMARY KEY (todo_id, depends_on));
INSERT OR REPLACE INTO todos (id, title, description, status, updated_at) VALUES ('cat-faq-page', 'Build cat FAQ page', 'Create index.html with dark styled vanilla JS FAQ accordion. Each Q/A section must use div.example and controlled answer content must use class details.', 'in_progress', CURRENT_TIMESTAMP);

