+      border-radius: 999px;
+      color: #d9ccff;
+      background: rgba(159, 122, 234, 0.12);
+      font-size: 0.82rem;
+      font-weight: 700;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2.5rem, 7vw, 5.1rem);
+      line-height: 0.95;
+      letter-spacing: -0.065em;
+    }
+
+    .intro {
+      max-width: 690px;
+      margin: 22px auto 0;
+      color: var(--muted);
+      font-size: 1.08rem;
+    }
+
+    .faq {
+      display: grid;
+      gap: 16px;
+      padding: 18px;
+      border: 1px solid var(--border);
+      border-radius: 30px;
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03));
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(22px);
+    }
+
+    .example {
+      overflow: hidden;
+      border: 1px solid var(--border);
+      border-radius: 22px;
+      background: var(--panel);
+      transition: border-color 180ms ease, background 180ms ease, transform 180ms ease;
+    }
+
+    .example:hover,
+    .example:focus-within {
+      border-color: rgba(159, 122, 234, 0.5);
+      background: rgba(23, 32, 55, 0.92);
+      transform: translateY(-1px);
+    }
+
+    .question {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      width: 100%;
+      gap: 18px;
+      padding: 22px 24px;
+      border: 0;
+      color: inherit;
+      background: transparent;
+      cursor: pointer;
+      font: inherit;
+      text-align: left;
+    }
+
+    .question span:first-child {
+      font-size: 1.05rem;
+      font-weight: 800;
+      letter-spacing: -0.015em;
+    }
+
+    .icon {
+      display: grid;
+      flex: 0 0 34px;
+      width: 34px;
+      height: 34px;
+      place-items: center;
+      border-radius: 50%;
+      color: #071016;
+      background: linear-gradient(135deg, var(--accent), var(--accent-2));
+      font-size: 1.35rem;
+      font-weight: 800;
+      line-height: 1;
+      transition: transform 180ms ease;
+    }
+
+    .question[aria-expanded="true"] .icon {
+      transform: rotate(45deg);
+    }
+
+    .details {
+      padding: 0 24px 24px;
+      color: var(--muted);
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 0;
+      padding-top: 2px;
+    }
+
+    .details strong {
+      color: var(--text);
+    }
+
+    @media (max-width: 640px) {
+      main {
+        width: min(100% - 20px, 920px);
+        padding: 42px 0;
+      }
+
+      .faq {
+        padding: 10px;
+        border-radius: 22px;
+      }
+
+      .question {
+        padding: 18px;
+      }
+
+      .details {
+        padding: 0 18px 20px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="hero" aria-labelledby="page-title">
+      <p class="eyebrow">Curious cat care</p>
+      <h1 id="page-title">Cat FAQ</h1>
+      <p class="intro">
+        Quick answers for common questions about feline behavior, health, feeding, and keeping indoor cats happy.
+      </p>
+    </section>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-1">
+          <span>Why do cats purr?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-1" hidden>
+          <p>
+            Cats often purr when they feel relaxed, but purring can also be a self-soothing behavior during stress,
+            discomfort, or recovery. Context matters: body posture, appetite, and energy level help tell the full story.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-2">
+          <span>How much should I feed my cat?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-2" hidden>
+          <p>
+            Feeding needs depend on age, weight, activity, and food type. Start with the food label's daily guidance,
+            adjust for body condition, and ask a veterinarian for a target calorie range if weight changes are needed.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-3">
+          <span>Do indoor cats need enrichment?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-3" hidden>
+          <p>
+            <strong>Yes.</strong> Indoor cats benefit from climbing spaces, scratching posts, puzzle feeders, window
+            perches, and short daily play sessions that mimic hunting: stalk, chase, catch, and then eat.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-4">
+          <span>Why does my cat knead blankets or people?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-4" hidden>
+          <p>
+            Kneading is a comforting behavior that begins in kittenhood. Many adult cats knead when they are content,
+            settling in for rest, or marking a cozy spot with scent glands in their paws.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-5">
+          <span>How often should I clean the litter box?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-5" hidden>
+          <p>
+            Scoop at least once daily and fully refresh litter as recommended for the litter type. A good rule is one
+            box per cat, plus one extra, placed in quiet and accessible areas.
+          </p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-6">
+          <span>When should I call a veterinarian?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-6" hidden>
+          <p>
+            Call promptly for appetite loss, repeated vomiting, labored breathing, sudden hiding, litter box straining,
+            rapid weight change, or any behavior that feels sharply different from your cat's normal routine.
+          </p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    const questions = document.querySelectorAll('.question');
+
+    questions.forEach((question) => {
+      question.addEventListener('click', () => {
+        const answer = document.getElementById(question.getAttribute('aria-controls'));
+        const isExpanded = question.getAttribute('aria-expanded') === 'true';
+
+        question.setAttribute('aria-expanded', String(!isExpanded));
+        answer.hidden = isExpanded;
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
